def _nn_probs_manifest_path(cache_dir: Path) -> Path:
    return cache_dir / "nn_probs_manifest.json"


def _load_nn_probs_from_cache(
    cache_dir: Path,
    seq_name: str,
    expected_len: int,
) -> np.ndarray:
    mpath = _nn_probs_manifest_path(cache_dir)
    manifest = json.loads(mpath.read_text())
    seqs: Dict[str, Any] = manifest.get("sequences") or {}
    if seq_name not in seqs:
        raise FileNotFoundError(
            f"{seq_name!r} not in nn probs manifest {mpath}",
        )
    rel = seqs[seq_name]["file"]
    arr = np.load(cache_dir / rel)
    if arr.shape != (expected_len, 11):
        raise ValueError(
            f"loaded probs shape {arr.shape} != ({expected_len}, 11) for {seq_name}",
        )
    return arr.astype(np.float32)


def _pick_device(preferred=None) -> torch.device:
    if preferred:
        return torch.device(preferred)
    if torch.cuda.is_available():
        return torch.device("cuda")
    if getattr(torch.backends, "mps", None) and torch.backends.mps.is_available():
        return torch.device("mps")
    return torch.device("cpu")


def tile_predict_v4(
    model: ProkaryoticModelV4,
    oh_fwd_6: np.ndarray,
    window: int,
    step: int,
    device: torch.device,
    batch_size: int = 4,
    *,
    full_sequence: bool = False,
    sd_channel: bool | None = None,
    stitch_mode: str = "mean",
) -> np.ndarray:
    """Sliding-window inference for v4. Returns (L_orig, 11) sigmoid probabilities.

    ``stitch_mode`` controls how overlapping tiles are combined (see
    ``tile_predict_v4_distribution``); "center" keeps, per base, the tile where the
    base is farthest from a window edge.

    If ``full_sequence`` is True, pads length to a multiple of ``model.pool_size``,
    runs a single forward pass covering the (padded) contig, then trims back to the
    original length (replaces ~10 kb tiling).
    """
    if sd_channel is None:
        sd_channel = bool(getattr(model, "_sd_channel", False)) or model.inp_size in (13, 16)
    phase_channel = bool(getattr(model, "_phase_channel", False)) or model.inp_size in (15, 16)
    numb_conv = len(model.conv_layers) + 1
    return tile_predict_v4_distribution(
        model,
        oh_fwd_6,
        window,
        step,
        device,
        batch_size,
        full_sequence=full_sequence,
        activation="sigmoid",
        sd_channel=sd_channel,
        phase_channel=phase_channel,
        numb_conv=numb_conv,
        cnn_stride=int(model.cnn_stride),
        stitch_mode=stitch_mode,
    )


def _load_checkpoint(
    path: str,
    device: torch.device,
    pool_size: int,
    numb_conv: int,
    numb_lstm: int,
    cnn_stride: int | None = None,
) -> ProkaryoticModelV4:
    try:
        ckpt = torch.load(path, map_location="cpu", weights_only=True)
    except TypeError:
        ckpt = torch.load(path, map_location="cpu")
    state = ckpt.get("model_state_dict", ckpt)
    ckpt_inp = int(state["initial_conv.weight"].shape[1]) if "initial_conv.weight" in state else 12
    model = load_prokaryotic_model_v4_from_checkpoint(
        path,
        pool_size=pool_size,
        cnn_stride=cnn_stride,
        numb_conv=numb_conv,
        numb_lstm=numb_lstm,
        device=device,
        inp_size=ckpt_inp,
    )
    sd_channel = bool(ckpt.get("enable_sd_channel", model.inp_size in (13, 16)))
    phase_channel = bool(ckpt.get("enable_phase_channel", model.inp_size in (15, 16)))
    model._sd_channel = sd_channel  # type: ignore[attr-defined]
    model._phase_channel = phase_channel  # type: ignore[attr-defined]
    return model


def _gene_ov_bp(s1: int, e1: int, s2: int, e2: int) -> int:
    return max(0, min(e1, e2) - max(s1, s2))


def _start_codon_interval(strand: str, s: int, e: int) -> Tuple[int, int]:
    if strand == "+":
        return (s, s + 3)
    return (e - 3, e)


def prodigal_overlap_filter(
    genes_fwd: List[Dict],
    genes_rev: List[Dict],
    same_strand_max_ov: int = 60,
    opposite_max_ov: int = 200,
    conflict_resolution: str = "length",
) -> Tuple[List[Dict], List[Dict], Dict]:
    """Same logic as ``eval_gene_level.prodigal_overlap_filter`` but operating
    on gene dicts rather than tuples.

    ``conflict_resolution`` decides which of two conflicting calls survives:

      length          longest first -- the historical default. Note this is a
                      hard sort, not a soft penalty: a short call is discarded
                      whatever its evidence, which is a structural short-gene
                      disadvantage at every cross-strand conflict.
      score           highest segmental ORF score first. The dicts DO carry
                      ``score`` (hmm_duration_decode.py:906), so the original
                      comment that "the HMM emits no explicit per-gene score"
                      is stale.
      score_per_base  score / length, since the raw score is a sum of per-base
                      log terms and therefore scales with gene length.
    """
    if conflict_resolution == "length":
        key = lambda t: -t[0]["length"]
    elif conflict_resolution == "score":
        key = lambda t: -float(t[0].get("score", 0.0))
    elif conflict_resolution == "score_per_base":
        key = lambda t: -float(t[0].get("score", 0.0)) / max(t[0]["length"], 1)
    else:
        raise ValueError(
            "conflict_resolution must be 'length', 'score' or 'score_per_base'"
        )
    tagged = [(g, "+") for g in genes_fwd] + [(g, "-") for g in genes_rev]
    tagged.sort(key=key)

    kept_p: List[Dict] = []
    kept_m: List[Dict] = []
    stats = {
        "n_in_fwd": len(genes_fwd), "n_in_rev": len(genes_rev),
        "drop_same_strand": 0, "drop_opp_start_overlap": 0, "drop_opp_gt_max": 0,
    }

    def first_violation(g: Dict, strand: str):
        s, e = g["start"], g["end"]
        same_kept = kept_p if strand == "+" else kept_m
        opp_kept = kept_m if strand == "+" else kept_p
        opp_str = "-" if strand == "+" else "+"
        for kg in same_kept:
            if _gene_ov_bp(s, e, kg["start"], kg["end"]) > same_strand_max_ov:
                return "same"
        sa0, sa1 = _start_codon_interval(strand, s, e)
        for kg in opp_kept:
            ks, ke = kg["start"], kg["end"]
            ov = _gene_ov_bp(s, e, ks, ke)
            if ov == 0:
                continue
            sb0, sb1 = _start_codon_interval(opp_str, ks, ke)
            if _gene_ov_bp(sa0, sa1, sb0, sb1) > 0:
                return "start"
            if ov > opposite_max_ov:
                return "opp"
        return None

    for g, strand in tagged:
        why = first_violation(g, strand)
        if why == "same":
            stats["drop_same_strand"] += 1
            continue
        if why == "start":
            stats["drop_opp_start_overlap"] += 1
            continue
        if why == "opp":
            stats["drop_opp_gt_max"] += 1
            continue
        (kept_p if strand == "+" else kept_m).append(g)

    stats["n_out_fwd"] = len(kept_p)
    stats["n_out_rev"] = len(kept_m)
    return kept_p, kept_m, stats
